code.C++:
#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    int missingNumber(vector<int>& nums) {
        long long n = nums.size();
        long long expected = n * (n + 1) / 2;
        long long sum = 0;
        for (int v : nums) sum += v;
        return (int)(expected - sum);
    }
};

